462	  Status ValidateLayout(const DataType& type) {
463	    // Check the data layout conforms to the spec
464	    const auto layout = type.layout();
465	
466	    if (data.length < 0) {
467	      return Status::Invalid("Array length is negative");
468	    }
469	
470	    if (layout.variadic_spec) {
471	      if (data.buffers.size() < layout.buffers.size()) {
472	        return Status::Invalid("Expected at least ", layout.buffers.size(),
473	                               " buffers in array of type ", type.ToString(), ", got ",
474	                               data.buffers.size());
475	      }
476	    } else if (data.buffers.size() != layout.buffers.size()) {
477	      return Status::Invalid("Expected ", layout.buffers.size(),
478	                             " buffers in array of type ", type.ToString(), ", got ",
479	                             data.buffers.size());
480	    }
481	
482	    // This check is required to avoid addition overflow below
483	    int64_t length_plus_offset = -1;
484	    if (AddWithOverflow(data.length, data.offset, &length_plus_offset)) {
485	      return Status::Invalid("Array of type ", type.ToString(),
486	                             " has impossibly large length and offset");
487	    }
488	
489	    for (int i = 0; i < static_cast<int>(data.buffers.size()); ++i) {
490	      const auto& buffer = data.buffers[i];
491	      const auto& spec = i < static_cast<int>(layout.buffers.size())
492	                             ? layout.buffers[i]
493	                             : *layout.variadic_spec;
494	
495	      if (buffer == nullptr) {
496	        continue;
497	      }
498	      int64_t min_buffer_size = 0;
499	      switch (spec.kind) {
500	        case DataTypeLayout::BITMAP:
501	          // If length == 0, buffer size can be 0 regardless of offset
502	          if (data.length > 0) {
503	            min_buffer_size = bit_util::BytesForBits(length_plus_offset);
504	          }
505	          break;
506	        case DataTypeLayout::FIXED_WIDTH:
507	          if (data.length > 0 && MultiplyWithOverflow(length_plus_offset, spec.byte_width,
508	                                                      &min_buffer_size)) {
509	            return Status::Invalid("Array of type ", type.ToString(),
510	                                   " has impossibly large length and offset");
511	          }
512	          break;
513	        case DataTypeLayout::ALWAYS_NULL:
514	          // XXX Should we raise on non-null buffer?
515	          continue;
516	        default:
517	          continue;
518	      }
519	      if (buffer->size() < min_buffer_size) {
520	        return Status::Invalid("Buffer #", i, " too small in array of type ",
521	                               type.ToString(), " and length ", data.length,
522	                               ": expected at least ", min_buffer_size, " byte(s), got ",
523	                               buffer->size());
524	      }
525	    }
526	    if (layout.has_dictionary && !data.dictionary) {
527	      return Status::Invalid("Array of type ", type.ToString(),
528	                             " must have dictionary values");
529	    }
530	    if (!layout.has_dictionary && data.dictionary) {
531	      return Status::Invalid("Unexpected dictionary values in array of type ",
532	                             type.ToString());
533	    }
534	    return Status::OK();
535	  }
