541	                             " nulls but no null bitmap");
542	    }
543	    if (data.null_count > data.length) {
544	      return Status::Invalid("Null count exceeds array length");
545	    }
546	    if (data.null_count < 0 && data.null_count != kUnknownNullCount) {
547	      return Status::Invalid("Negative null count");
548	    }
549	
