552	        int64_t actual_null_count;
553	        if (HasValidityBitmap(data.type->id()) && data.buffers[0]) {
554	          // Do not call GetNullCount() as it would also set the `null_count` member
555	          actual_null_count = data.length - CountSetBits(data.buffers[0]->data(),
