557	        } else if (data.type->storage_id() == Type::NA) {
558	          actual_null_count = data.length;
559	        } else {
560	          actual_null_count = 0;
561	        }
562	        if (actual_null_count != data.null_count) {
563	          return Status::Invalid("null_count value (", data.null_count,
564	                                 ") doesn't match actual number of nulls in array (",
565	                                 actual_null_count, ")");
566	        }
567	      }
568	    }
569	    return Status::OK();
