using arrow::internal::AddWithOverflow;
using arrow::internal::MultiplyWithOverflow;

[[noreturn]] void throwCorruptedArrowData(const std::string & format_name, const String & message)
{
    throw Exception(ErrorCodes::INCORRECT_DATA, "Corrupted {} data: {}", format_name, message);
}

/// Returns whether the row at logical position `i` is null according to the
/// validity bitmap. Safe to call only after the bitmap buffer size has been
/// validated (see the BITMAP branch in checkArrowArrayDataConsistency).
bool arrowArrayDataIsNull(const arrow::ArrayData & data, int64_t i)
{
    if (data.buffers.empty() || !data.buffers[0])
        return false;
    return !arrow::bit_util::GetBit(data.buffers[0]->data(), data.offset + i);
}

/// Validate the offsets buffer of a variable-length / list-like array. Such
/// types need `length + offset + 1` offset entries, while the generic layout
/// loop only guarantees `length + offset`.
void checkOffsetsBufferSize(
    const arrow::ArrayData & data, int64_t length_plus_offset, int64_t offset_width, const std::string & format_name)
{
    if (data.length <= 0)
        return;
    if (data.buffers.size() < 2 || !data.buffers[1])
        throwCorruptedArrowData(
            format_name,
            fmt::format("array of type {} with length {} is missing its offsets buffer", data.type->ToString(), data.length));

    int64_t needed_entries = 0;
    int64_t needed_bytes = 0;
    if (AddWithOverflow(length_plus_offset, static_cast<int64_t>(1), &needed_entries)
        || MultiplyWithOverflow(needed_entries, offset_width, &needed_bytes))
        throwCorruptedArrowData(
            format_name, fmt::format("array of type {} has impossibly large length and offset", data.type->ToString()));

    if (data.buffers[1]->size() < needed_bytes)
        throwCorruptedArrowData(
            format_name,
            fmt::format(
                "offsets buffer in array of type {} with length {} is too small: expected at least {} bytes, got {}",
                data.type->ToString(),
                data.length,
                needed_bytes,
                data.buffers[1]->size()));
}

/// Validate that list/large-list/map offsets are non-negative, monotonically
/// non-decreasing and stay within the child values array.
template <typename OffsetType>
void checkListOffsets(const arrow::ArrayData & data, const std::string & format_name)
{
    if (data.length <= 0)
        return;
    if (data.child_data.empty() || !data.child_data[0])
        throwCorruptedArrowData(
            format_name, fmt::format("list array of type {} has no child values array", data.type->ToString()));

    const int64_t child_length = data.child_data[0]->length;
    const auto * offsets = data.GetValues<OffsetType>(1);

    int64_t prev = static_cast<int64_t>(offsets[0]);
    if (prev < 0)
        throwCorruptedArrowData(
            format_name, fmt::format("list array of type {} has a negative offset {}", data.type->ToString(), prev));

    for (int64_t i = 1; i <= data.length; ++i)
    {
        const int64_t cur = static_cast<int64_t>(offsets[i]);
        if (cur < prev)
            throwCorruptedArrowData(
                format_name,
                fmt::format(
                    "list array of type {} has non-monotonic offsets: offset[{}]={} < offset[{}]={}",
                    data.type->ToString(),
                    i,
                    cur,
                    i - 1,
                    prev));
        if (cur > child_length)
            throwCorruptedArrowData(
                format_name,
                fmt::format(
                    "list array of type {} has offset {} at row {} pointing past the end of its child values array of "
                    "length {}",
                    data.type->ToString(),
                    cur,
                    i - 1,
                    child_length));
        prev = cur;
    }
}

/// Validate the per-view metadata of a StringView/BinaryView array: sizes must
/// be non-negative and out-of-line references must stay within their variadic
/// data buffer.
void checkBinaryViews(const arrow::ArrayData & data, const std::string & format_name)
{
    if (data.length <= 0)
        return;
    if (data.buffers.size() < 2 || !data.buffers[1])
        throwCorruptedArrowData(
            format_name, fmt::format("view array of type {} is missing its views buffer", data.type->ToString()));

    const auto * views = data.GetValues<arrow::BinaryViewType::c_type>(1);
    const size_t num_data_buffers = data.buffers.size() > 2 ? data.buffers.size() - 2 : 0;

    for (int64_t i = 0; i < data.length; ++i)
    {
        if (arrowArrayDataIsNull(data, i))
            continue;

        const auto & view = views[i];
        const int32_t size = view.size();
        if (size < 0)
            throwCorruptedArrowData(
                format_name, fmt::format("view array of type {} has a negative size {} at row {}", data.type->ToString(), size, i));

        if (view.is_inline())
            continue;

        const int32_t buffer_index = view.ref.buffer_index;
        const int32_t view_offset = view.ref.offset;
        if (buffer_index < 0 || static_cast<size_t>(buffer_index) >= num_data_buffers)
            throwCorruptedArrowData(
                format_name,
                fmt::format(
                    "view array of type {} references data buffer {} at row {} but only {} data buffers are present",
                    data.type->ToString(),
                    buffer_index,
                    i,
                    num_data_buffers));
        if (view_offset < 0)
            throwCorruptedArrowData(
                format_name,
                fmt::format("view array of type {} has a negative offset {} at row {}", data.type->ToString(), view_offset, i));

        const auto & data_buffer = data.buffers[2 + buffer_index];
        const int64_t end = static_cast<int64_t>(view_offset) + static_cast<int64_t>(size);
        if (!data_buffer || end > data_buffer->size())
            throwCorruptedArrowData(
                format_name,
                fmt::format(
                    "view array of type {} references range [{}, {}) of data buffer {} at row {} but that buffer holds only "
                    "{} bytes",
                    data.type->ToString(),
                    view_offset,
                    end,
                    buffer_index,
                    i,
                    data_buffer ? data_buffer->size() : 0));
    }
}

